    }
    if (inClosedPeriod(this.periods.list(), c.date)) {
      this.setRowError(c.id, CLOSED);
      return;
    }
    const url = `/api/sheets/${encodeURIComponent(sheet)}/claims/${c.id}/proof`;
    try {
      this.saved.emit(await firstValueFrom(this.http.post<Claim>(url, null)));
